function nagdy_add_custom_checkout_fields(  ) {
    $specific_product_ids = array( 73, 456 );
    $product_in_cart = false;

    foreach ( WC()->cart->get_cart() as $cart_item_key => $cart_item ) {
        if ( in_array($cart_item['product_id'], $specific_product_ids) ) {
            $product_in_cart = true;
            break;
        }
    }

    if ( $product_in_cart ) {
        woocommerce_form_field( 'request_info', array(
            'type'          => 'textarea',
            'class'         => array('request_info form-row-wide'),
            'label'         => __('More Information', 'woocommerce'),
            'placeholder'   => __('Please tell me more about the request', 'woocommerce'),
            'required'      => true,
        ), WC()->checkout()->get_value( 'request_info' ));
    }
}

