add_filter( 'woocommerce_package_rates', function( $rates, $package ) {
    // Only add (COD) if COD is selected in the checkout (using $_POST)
    $chosen_payment_method = WC()->session->get( 'chosen_payment_method' );

    // If during cart display phase, the chosen payment method might not be set yet,
    // so optionally display for all rates and adjust at order save time.
    if ( $chosen_payment_method === 'cod' ) {
        foreach ( $rates as $rate_key => $rate ) {
            if ( strpos( $rate->label, '(COD)' ) === false ) {
                $rates[$rate_key]->label .= ' (COD)';
            }
        }
    }
    return $rates;
}, 20, 2 );

