add_filter( 'woocommerce_package_rates', 'custom_hide_shipping_methods_based_on_payment', 10, 2 );

function custom_hide_shipping_methods_based_on_payment( $rates, $package ) {
    // Get chosen payment method
    $chosen_payment_method = WC()->session->get( 'chosen_payment_method' );

    // Define shipping rates to hide for COD
    $hide_for_cod = array( 'flat_rate:11', 'free_shipping:1' ); // Update with your IDs

    // Define shipping rates to hide for other payment methods
    $hide_for_others = array( 'flat_rate:17', 'free_shipping:16' ); // Update with your IDs

    foreach ( $rates as $rate_key => $rate ) {

        if ( 'cod' === $chosen_payment_method && in_array( $rate_key, $hide_for_cod ) ) {
            unset( $rates[ $rate_key ] );
        }

        if ( 'cod' !== $chosen_payment_method && in_array( $rate_key, $hide_for_others ) ) {
            unset( $rates[ $rate_key ] );
        }
    }

    return $rates;
}


