add_filter('woocommerce_variable_price_html', 'custom_variable_price_format', 10, 2);

function custom_variable_price_format($price, $product) {
    // Only apply on shop/archive pages, not single product
    if (is_product()) {
        return $price;
    }

    $min_price = $product->get_variation_price('min', true);
    $max_price = $product->get_variation_price('max', true);
    $min_regular = $product->get_variation_regular_price('min', true);
    $max_regular = $product->get_variation_regular_price('max', true);

    // If product is on sale
    if ($min_price < $min_regular) {
        $price = '<del>' . wc_price($min_regular) . '</del> <ins>' . wc_price($min_price) . '</ins>';
    } else {
        $price = wc_price($min_price);
    }

    return $price;
}

add_filter('woocommerce_variable_sale_price_html', 'woosuite_custom_variable_product_price', 10, 2 );
add_filter('woocommerce_variable_price_html', 'woosuite_custom_variable_product_price', 10, 2 );

function woosuite_custom_variable_product_price( $price, $product ) {
    // Check if it's a variable product
    if ( $product->is_type('variable') ) {
        // Get all variations for the product
        $variations = $product->get_available_variations();

        // Loop through variations to find the minimum price
        $min_price = null;
        foreach ( $variations as $variation ) {
            $variation_price = floatval($variation['display_price']);

            // Set the initial minimum price or update it if a lower price is found
            if ( $min_price === null || $variation_price < $min_price ) {
                $min_price = $variation_price;
            }
        }

        // Display the minimum price
        if ( $min_price !== null ) {
            $price = wc_price($min_price);
        }
    }

    return $price;
}

// Elementor Dynamic Tag: Discount Percentage
add_action('elementor/dynamic_tags/register', function($dynamic_tags) {
    class Discount_Percentage_Tag extends \Elementor\Core\DynamicTags\Tag {
        public function get_name() {
            return 'discount-percentage';
        }

        public function get_title() {
            return 'Discount Percentage';
        }

        public function get_group() {
            return 'woocommerce';
        }

        public function get_categories() {
            return [ \Elementor\Modules\DynamicTags\Module::TEXT_CATEGORY ];
        }

        public function render() {
            global $product;

            if (!$product || !$product->is_on_sale()) return;

            $regular = $product->get_regular_price();
            $sale    = $product->get_sale_price();

            if (!$regular || !$sale) return;

            $percentage = round( ( ($regular - $sale) / $regular ) * 100 );

            echo "-{$percentage}%";
        }
    }

    $dynamic_tags->register_tag('Discount_Percentage_Tag');
});

