    ?>
    <script>
    (function($) {
        var url = '<?php echo esc_url( wc_get_checkout_url() ); ?>';

        // Covers standard WooCommerce AJAX + WC Blocks
        $(document).on('added_to_cart wc-blocks_added_to_cart', function() {
            window.location.href = url;
        });

        // Covers Elementor "add-to-cart" link buttons
        $(document).on('click', '[href*="add-to-cart"]', function(e) {
            var match = $(this).attr('href').match(/add-to-cart=(\d+)/);
            if ( !match ) return;
            e.preventDefault();
            $.post(wc_add_to_cart_params.ajax_url, {
                action: 'woocommerce_add_to_cart',
                product_id: match[1],
                quantity: 1
            }).always(function() {
                window.location.href = url;
            });
        });
    })(jQuery);
    </script>
