function hide_paid_shipping_above_200_sar( $rates, $package ) {
    $cart_total = WC()->cart->subtotal; // اجمالي الطلب قبل الخصومات والضرائب
    $free_shipping_id = '';
    $paid_shipping_id = '';

    // البحث عن معرفات وسائل الشحن
    foreach ( $rates as $rate_id => $rate ) {
        if ( strpos( strtolower( $rate->label ), 'مجاني' ) !== false ) {
            $free_shipping_id = $rate_id;
        } else {
            $paid_shipping_id = $rate_id;
        }
    }

    // إذا كان المجموع أكبر من أو يساوي 200 ريال، نخفي الشحن المدفوع
    if ( $cart_total >= 200 && $paid_shipping_id ) {
        unset( $rates[$paid_shipping_id] );
    }

    return $rates;
}
