add_filter("woocommerce_currency_symbol", "change_currency_symbol_based_on_language", 10, 2);

function change_currency_symbol_based_on_language($currency_symbol, $currency) {
    // Check if the currency is Kuwaiti Dinar
    if ($currency === "KWD") {
        // Check WPML's current language setting
        $current_language = apply_filters('wpml_current_language', NULL);

        // Set currency symbol based on the current language
        if ($current_language === "en") {
            $currency_symbol = "KD";
        } else {
            $currency_symbol = "د.ك";
        }
    }
    return $currency_symbol;
}






